-- Corrected 3D puppet animations of KineAid exercises:
--   cat-camel: hands and knees stay on the floor while the back rounds/arches
--   wall-slide: camera behind the patient, so it is not behind the wall
-- (Copies that kines made earlier keep their own animation.) Safe to run more than once.

update public.exercises set puppet = '{"base":"quadruped","keyframes":[{"pose":{},"move":1.2,"hold":0.3},{"pose":{"pelvis":[53,0,0],"l_hip":[-53,0,3],"r_hip":[-53,0,-3],"l_knee":[90,0,0],"r_knee":[90,0,0],"l_ankle":[75,0,0],"r_ankle":[75,0,0],"spine":[25,0,0],"chest":[12,0,0],"l_shoulder":[-90,0,4],"r_shoulder":[-90,0,-4],"l_elbow":[0,0,0],"r_elbow":[0,0,0],"neck":[35,0,0]},"move":1.5,"hold":1},{"pose":{},"move":1.2,"hold":0.3},{"pose":{"pelvis":[94,0,0],"l_hip":[-94,0,3],"r_hip":[-94,0,-3],"l_knee":[90,0,0],"r_knee":[90,0,0],"l_ankle":[75,0,0],"r_ankle":[75,0,0],"spine":[-15,0,0],"chest":[-8,0,0],"l_shoulder":[-71,0,4],"r_shoulder":[-71,0,-4],"l_elbow":[0,0,0],"r_elbow":[0,0,0],"neck":[-25,0,0]},"move":1.5,"hold":1}],"anchor":["l_knee","r_knee"],"props":[{"type":"mat"}],"view":{"az":90,"el":10},"highlight":["abdomen","chest"]}'::jsonb where source = 'kineaid' and source_id = 'cat-camel';
update public.exercises set puppet = '{"base":"standing","keyframes":[{"pose":{"l_shoulder":[-90,0,15],"r_shoulder":[-90,0,-15],"l_elbow":[-90,0,0],"r_elbow":[-90,0,0]},"move":1.5,"hold":0.5},{"pose":{"pelvis":[8,0,0],"l_hip":[-8,0,2],"r_hip":[-8,0,-2],"l_knee":[0,0,0],"r_knee":[0,0,0],"l_ankle":[0,0,0],"r_ankle":[0,0,0],"l_shoulder":[-150,0,15],"r_shoulder":[-150,0,-15],"l_elbow":[-15,0,0],"r_elbow":[-15,0,0]},"move":1.5,"hold":0.5}],"anchor":["l_sole","r_sole"],"props":[{"type":"wall","at":["l_wrist","r_wrist"],"frame":0,"offset":[0,0,0.045],"rotY":180}],"view":{"az":130,"el":15},"highlight":["l_upperarm","r_upperarm"]}'::jsonb where source = 'kineaid' and source_id = 'wall-slide';
